// Why Code: normalize level commands (/basico, /intermedio, /avanzado), uiLanguage (es|en), and CEFR directives in one pass before AI Agent.
const LEVEL_MAP = {
  basico: {
    command: '/basico',
    cefr: 'A1-A2',
    directiveEs: 'Fase BÁSICO (/basico · CEFR A1-A2): vocabulario cotidiano, saludos, presente e introduce pronunciación fonética sencilla. Explica en español claro.',
    directiveEn: 'Phase BASIC (/basico · CEFR A1-A2): everyday vocabulary, greetings, present tense, and gentle phonetic hints. Explain clearly in English.'
  },
  intermedio: {
    command: '/intermedio',
    cefr: 'B1-B2',
    directiveEs: 'Fase INTERMEDIO (/intermedio · CEFR B1-B2): diálogos naturales en francés, passé composé/imparfait/futur, conectores lógicos y correcciones breves en español.',
    directiveEn: 'Phase INTERMEDIATE (/intermedio · CEFR B1-B2): natural French dialogues, passé composé/imparfait/futur, connectors, and concise feedback in English.'
  },
  avanzado: {
    command: '/avanzado',
    cefr: 'C1-C2',
    directiveEs: 'Fase AVANZADO (/avanzado · CEFR C1-C2): inmersión casi total en francés, subjuntivo, registro formal/idiomático, matices estilísticos y análisis discursivo.',
    directiveEn: 'Phase ADVANCED (/avanzado · CEFR C1-C2): near-total French immersion, subjunctive, formal/idiomatic register, stylistic nuance, and discourse feedback.'
  }
};

return $input.all().map((item) => {
  const body = item.json?.body ?? item.json ?? {};
  const rawMessage = String(body.message ?? '').trim();
  const cmdMatch = rawMessage.match(/^\/(basico|intermedio|avanzado)(?:\s+(.*))?$/i);
  const detectedLevel = cmdMatch ? cmdMatch[1].toLowerCase() : String(body.level ?? 'basico').toLowerCase();
  const level = LEVEL_MAP[detectedLevel] ? detectedLevel : 'basico';
  const uiLanguage = String(body.uiLanguage ?? 'es').toLowerCase() === 'en' ? 'en' : 'es';
  const cleanMessage = cmdMatch ? (cmdMatch[2]?.trim() || `Activar fase ${LEVEL_MAP[level].command}`) : rawMessage;
  const sessionId = String(body.sessionId || 'lueurfle-default-session');
  const meta = LEVEL_MAP[level];

  return {
    json: {
      sessionId,
      message: cleanMessage,
      rawMessage,
      level,
      command: meta.command,
      cefr: meta.cefr,
      uiLanguage,
      levelDirective: uiLanguage === 'en' ? meta.directiveEn : meta.directiveEs,
      systemPromptAddon: String(body.systemPrompt ?? '')
    }
  };
});
